import type {EntryPointProps} from 'react-relay'
import {EntryPointContainer} from 'react-relay'

import type {AgentsOverviewPageEntryPoint} from '../../pages/AgentsPages/AgentsOverviewPage/AgentsOverviewPage.entryPoint'
import WelcomeScreen from '../../pages/PipelinesPages/AgentsPage/WelcomeScreen/WelcomeScreen'

export type AppAgentTypeNestedEntryPoints = {
  common?: typeof AgentsOverviewPageEntryPoint
}

export default function AppAgentOverview({
  entryPoints,
}: EntryPointProps<{}, AppAgentTypeNestedEntryPoints, {}, {}>) {
  const {common} = entryPoints

  if (common) {
    return <EntryPointContainer entryPointReference={common} props={{}} />
  }

  return <WelcomeScreen />
}
export type AppAgentOverviewComponent = typeof AppAgentOverview
